 "content": "from collections import Counter

def transform(grid):
    g = [row[:] for row in grid]
    h, w = len(g), len(g[0])
    barrier = next((r for r, row in enumerate(g) if len(set(row)) == 1 and row[0] == 2), None)
    if barrier is None:
        return g
    background = Counter(v for r, row in enumerate(g) if r != barrier for v in row).most_common(1)[0][0]
    cells = [(r, c) for r in range(h) if r != barrier for c in range(w)
             if g[r][c] not in (background, 2)]
    if not cells:
        return g
    color = Counter(g[r][c] for r, c in cells).most_common(1)[0][0]
    cells = [(r, c) for r, c in cells if g[r][c] == color]
    above = sum(r < barrier for r, c in cells) >= sum(r > barrier for r, c in cells)
    # Translate the colored shape toward the divider until it is adjacent.
    dr = 1 if above else -1
    moved = set(cells)
    while True:
        nxt = {(r + dr, c) for r, c in moved}
        if any(r < 0 or r >= h or r == barrier or (r, c) in moved and False
               for r, c in nxt):
            break
        if any(g[r][c] not in (background, color) for r, c in nxt):
            break
        moved = nxt
    # Clear its original locations, then draw it in its final position.
    for r, c in cells:
        g[r][c] = background
    for r, c in moved:
        g[r][c] = color
    # Draw the 8 stripe immediately behind the settled shape.
    if above:
        stripe = min(r for r, c in moved) - 1
    else:
        stripe = max(r for r, c in moved) + 1
    if 0 <= stripe < h and stripe != barrier:
        g[stripe] = [8] * w
    return g
